#!/bin/sh
# gen-static.sh — turn the built dashboard into a Nim module, so `nim c` alone produces a binary
# that serves the pages from memory.
#
#   gen-static.sh <dist-dir> <out-file>      (run from the repo root)
#
# Deterministic on purpose: files sorted, no timestamps, no absolute paths, no content hashes.
# Two runs over the same dist produce a byte-identical module on any machine, which is what makes
# "the committed dist is stale" a git diff instead of a guess. The paths inside staticRead are
# relative to the generated file, so the module survives being built on a Mac, in CI and in the
# container image alike.
set -eu

dist="${1:?usage: gen-static.sh <dist-dir> <out-file>}"
out="${2:?usage: gen-static.sh <dist-dir> <out-file>}"

[ -d "$dist" ] || { echo "gen-static: dist dir missing: $dist" >&2; exit 1; }
[ -d "$(dirname "$out")" ] || mkdir -p "$(dirname "$out")"

# Relative path from the generated file's directory to the dist file, computed without realpath
# (macOS and Rocky 9 disagree about its flags).
relpath() { # relpath <from-file> <to-file>
  awk -v from="$1" -v to="$2" 'BEGIN{
    n = split(from, a, "/"); m = split(to, b, "/"); k = n - 1;
    i = 1; while (i <= k && i <= m - 1 && a[i] == b[i]) i++;
    s = "";
    for (j = i; j <= k; j++) s = s "../";
    for (j = i; j <= m; j++) s = s b[j] (j < m ? "/" : "");
    print (s == "" ? "." : s);
  }'
}

tmp="$out.tmp"
{
  echo "# Generated by tools/gen-static.sh from $dist. Do not edit, and do not hand-commit a change here."
  echo "# Rebuild: (cd apps/web && pnpm run build) && sh tools/gen-static.sh apps/web/dist $out"
  echo "import std/tables"
  echo ""
  echo "type StaticFile* = object"
  echo "  body*: string"
  echo "  contentType*: string"
  echo ""
  echo "type StaticEntry* = tuple[path: string, contentType: string, body: string]"
  echo ""
  # `const`, not a proc body: staticRead is a compile-time call and Nim rejects it anywhere else.
  echo "const staticEntries* = ["
} >"$tmp"

count=0
find "$dist" -type f | LC_ALL=C sort | while IFS= read -r f; do
  rel="${f#"$dist"/}"
  case "$rel" in
    *.html) ct="text/html; charset=utf-8" ;;
    *.js | *.mjs) ct="text/javascript; charset=utf-8" ;;
    *.css) ct="text/css; charset=utf-8" ;;
    *.woff2) ct="font/woff2" ;;
    *.json) ct="application/json" ;;
    *.svg) ct="image/svg+xml" ;;
    *.png) ct="image/png" ;;
    *.ico) ct="image/x-icon" ;;
    *) ct="application/octet-stream" ;;
  esac
  printf '  (path: "/%s", contentType: "%s", body: staticRead("%s")),\n' \
    "$rel" "$ct" "$(relpath "$out" "$f")" >>"$tmp"
  echo x >>"$tmp.count"
done

{
  echo "]"
  echo ""
  echo "proc staticFileTable*(): Table[string, StaticFile] ="
  echo "  result = initTable[string, StaticFile](staticEntries.len)"
  echo "  for e in staticEntries:"
  echo "    result[e.path] = StaticFile(body: e.body, contentType: e.contentType)"
} >>"$tmp"

count="$(wc -l <"$tmp.count" 2>/dev/null | tr -d ' ' || echo 0)"
rm -f "$tmp.count"
mv "$tmp" "$out"
echo "gen-static: $count files embedded from $dist into $out"
